"""Snap span times to a fixed step and label the results."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span

def check_step(step: int) -> None:
    """Steps are whole minutes that divide an hour."""
    if not isinstance(step, int) or step <= 0 or 60 % step:
        raise ValueError(f"bad rounding step: {step!r}")

# ---
def round_minute(value: int, step: int) -> int:
    """Nearest multiple of step. Exact halves round up."""
    check_step(step)
    return (value * 2 + step) // (step * 2) * step

def duration_text(span: Span) -> str:
    hours, mins = divmod(span.minutes, 60)
    return f"{hours}h {mins}m"

# ---
def round_span(span: Span, step: int) -> Span:
    """Round both ends. ValueError if the span collapses."""
    return Span(
        round_minute(span.start, step),
        round_minute(span.end, step)
    )

def span_label(span: Span) -> str:
    return f"{format_span(span)} ({duration_text(span)})"

# ---
def rounded_labels(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Labels such as 09:00-17:15 (8h 15m), one per span."""
    check_step(step)
    snapped = [round_span(item, step) for item in spans]
    return [span_label(item) for item in snapped]

