import unittest

from hourglass.rounding import round_minute, rounded_labels
from hourglass.parsing import parse_span
from hourglass.models import Span

class RoundMinuteTests(unittest.TestCase):
    def test_rounds_down(self):
        self.assertEqual(round_minute(66, 15), 60)

    def test_rounds_up(self):
        self.assertEqual(round_minute(68, 15), 75)

    def test_half_rounds_up(self):
        self.assertEqual(round_minute(62, 4), 64)

class LabelTests(unittest.TestCase):
    def test_label_for_snapped_span(self):
        spans = [parse_span("09:04-17:12")]
        self.assertEqual(
            rounded_labels(spans, 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_one_label_per_span(self):
        spans = [Span(541, 600), Span(601, 725)]
        labels = rounded_labels(spans, 30)
        self.assertEqual(
            labels,
            ["09:00-10:00 (1h 0m)", "10:00-12:00 (2h 0m)"]
        )

    def test_end_of_day(self):
        spans = [parse_span("22:00-24:00")]
        self.assertEqual(
            rounded_labels(spans, 60),
            ["22:00-24:00 (2h 0m)"]
        )

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            rounded_labels([Span(541, 543)], 15)

class BadStepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -5, 7, 45, 90, 2.5):
            with self.assertRaises(ValueError):
                rounded_labels([Span(0, 60)], step)

    def test_good_steps_work(self):
        for step in (1, 5, 10, 15, 20, 30, 60):
            labels = rounded_labels([Span(0, 120)], step)
            self.assertEqual(
                labels,
                ["00:00-02:00 (2h 0m)"]
            )
